  [427069] = { "Shield Masteryのアビリティを得ます：\n\n$I1\n盾を装備している間、与えるすべての物理ダメージが$N1%増加し、自分に対するすべてのDisarm効果の効果時間が$N2%短縮されます。この効果は、Disarmの効果時間を短縮する他の効果とは重複しません。", nil, 0xc6e53f92, nil, "um" },
