  [427076] = { "頭部にTaste for Bloodのルーンを刻みます：\n\n$I1\nRendがダメージを与えるたびに、Overpowerが$D1の間、または1回攻撃するまで使用可能になります。この効果は$D2に一度しか発生しません。", nil, 0x372b5a47, nil, "um" },
  [427078] = { "頭部にVigilanceのルーンを刻みます：\n\n$I1\nパーティーまたはレイドのメンバー一人に守護の視線を向け、そのメンバーが受けるダメージを$N1%軽減し、そのメンバーが生み出す脅威の$N2%を自分に移します。さらに、そのメンバーが攻撃を受けるたびにTauntのクールダウンがリセットされます。効果時間は$D1です。この効果は一度に一人の対象にしか付与できません。", nil, 0x61f07c95, nil, "um" },
